package com.frostsecurity.extreme.commands;
import com.frostsecurity.extreme.dashboard.DashboardScreen; import com.frostsecurity.extreme.core.SecurityEngine; import com.frostsecurity.extreme.network.NetworkMonitor; import net.fabricmc.fabric.api.client.command.v2.ClientCommandManager; import net.fabricmc.fabric.api.client.command.v2.ClientCommandRegistrationCallback; import net.minecraft.client.MinecraftClient; import net.minecraft.text.Text;
public final class FrostCommands { public static void register(){ClientCommandRegistrationCallback.EVENT.register((d,r)->d.register(ClientCommandManager.literal("frostscan").executes(c->{MinecraftClient.getInstance().setScreen(new DashboardScreen());return 1;}).then(ClientCommandManager.literal("info").executes(c->{c.getSource().sendFeedback(Text.literal(NetworkMonitor.snapshot().summary()));return 1;})).then(ClientCommandManager.literal("analyze").executes(c->{SecurityEngine.evaluate();c.getSource().sendFeedback(Text.literal("Análise passiva executada."));return 1;})).then(ClientCommandManager.literal("network").executes(c->{MinecraftClient.getInstance().setScreen(new DashboardScreen());return 1;})).then(ClientCommandManager.literal("alerts").executes(c->{c.getSource().sendFeedback(Text.literal("Alertas: "+SecurityEngine.findings().size()));return 1;})).then(ClientCommandManager.literal("history").executes(c->{c.getSource().sendFeedback(Text.literal("Histórico persistido em frostscan-data."));return 1;})).then(ClientCommandManager.literal("report").executes(c->{c.getSource().sendFeedback(Text.literal("Use o botão Gerar relatório no painel."));return 1;})).then(ClientCommandManager.literal("packets").executes(c->{MinecraftClient.getInstance().setScreen(new DashboardScreen());return 1;})).then(ClientCommandManager.literal("vulnerabilities").executes(c->{c.getSource().sendFeedback(Text.literal("Consulta local de vulnerabilidades disponível via banco de dados."));return 1;})).then(ClientCommandManager.literal("plugins").executes(c->{c.getSource().sendFeedback(Text.literal("Plugins: somente componentes realmente observados ou fornecidos pelo administrador."));return 1;})).then(ClientCommandManager.literal("permissions").executes(c->{c.getSource().sendFeedback(Text.literal("Permissões: importe arquivos locais fornecidos pelo administrador."));return 1;})).then(ClientCommandManager.literal("export").executes(c->{c.getSource().sendFeedback(Text.literal("Exportação: use o gerador de relatórios."));return 1;})).then(ClientCommandManager.literal("lab").executes(c->{c.getSource().sendFeedback(Text.literal("Laboratório sintético disponível no código e documentação."));return 1;})).then(ClientCommandManager.literal("settings").executes(c->{c.getSource().sendFeedback(Text.literal("Configuração em config/frostscan.json."));return 1;})).then(ClientCommandManager.literal("stop").executes(c->{c.getSource().sendFeedback(Text.literal("Não há tarefa invasiva em execução."));return 1;})).then(ClientCommandManager.literal("help").executes(c->{c.getSource().sendFeedback(Text.literal("/frostscan [info|analyze|network|alerts|history|report|stop|help]"));return 1;}))));}}
